// storeDeleteCall calls Delete on subject with the arguments args, and
// returns the values of the call beside its error.
func storeDeleteCall(ctx context.Context, subject reference.Store, args []any) ([]any, error) {
	a0, _ := args[0].(string)
	return nil, subject.Delete(ctx, a0)
}

// storeReference returns the function that applies an operation of a
// history to the reference r by the name of its callable.
func storeReference(r reference.Store) func(context.Context, string, []any) conform.Output {
	return func(ctx context.Context, operation string, args []any) conform.Output {
		var values []any
		var err error
		switch operation {
		case "Get":
			values, err = storeGetCall(ctx, r, args)
		case "Put":
			values, err = storePutCall(ctx, r, args)
		case "Delete":
			values, err = storeDeleteCall(ctx, r, args)
		}
		return conform.OutputOf(err, values...)
	}
}

