type journalOverEmbedded = reference.Journal

// journalOver is a subject of Journal whose callables call spend and
// return their zero results. The planted defect of a ceiling passes a
// spend that exceeds the ceiling.
type journalOver struct {
	journalOverEmbedded
	spend func()
}

// Append calls spend and returns its zero results.
func (o journalOver) Append(context.Context, string) (r0 int, r1 error) {
	o.spend()
	return r0, r1
}

// At calls spend and returns its zero results.
func (o journalOver) At(context.Context, int) (r0 string, r1 error) {
	o.spend()
	return r0, r1
}

// Len calls spend and returns its zero results.
