// journalAppendCall calls Append on subject with the arguments args, and
// returns the values of the call beside its error.
func journalAppendCall(ctx context.Context, subject reference.Journal, args []any) ([]any, error) {
	a0, _ := args[0].(string)
	r0, err := subject.Append(ctx, a0)
	return []any{r0}, err
}

// journalAtCall calls At on subject with the arguments args, and returns
// the values of the call beside its error.
func journalAtCall(ctx context.Context, subject reference.Journal, args []any) ([]any, error) {
	a0, _ := args[0].(int)
	r0, err := subject.At(ctx, a0)
	return []any{r0}, err
}

// journalLenCall calls Len on subject with the arguments args, and returns
// the values of the call beside its error.
func journalLenCall(ctx context.Context, subject reference.Journal, args []any) ([]any, error) {
	r0, err := subject.Len(ctx)
	return []any{r0}, err
}

// journalReference returns the function that applies an operation of a
// history to the reference r by the name of its callable.
func journalReference(r reference.Journal) func(context.Context, string, []any) conform.Output {
	return func(ctx context.Context, operation string, args []any) conform.Output {
		var values []any
		var err error
		switch operation {
		case "Append":
			values, err = journalAppendCall(ctx, r, args)
		case "At":
			values, err = journalAtCall(ctx, r, args)
		case "Len":
			values, err = journalLenCall(ctx, r, args)
		}
		return conform.OutputOf(err, values...)
	}
}

