// RunFifoSuite applies the checks of Fifo, and the checks that opts add,
// to a fresh subject of newSubject for each check.
func RunFifoSuite[T reference.Fifo](t *testing.T, newSubject func() T, opts ...FifoOption) {
	t.Helper()
	RunFifoSuiteFromHandle(t, func(*FifoHandle) T { return newSubject() }, opts...)
}

// RunFifoSuiteFromHandle applies the same checks to a subject that
// newSubject builds from the handle of each check.
func RunFifoSuiteFromHandle[T reference.Fifo](t *testing.T, newSubject func(h *FifoHandle) T, opts ...FifoOption) {
	t.Helper()
	conform.Run(t, FifoSuite(), fifoSubjects(newSubject), opts...)
}

// FuzzFifoSuite registers on f the fuzz target of the property checks of
// callable, on a subject that newSubject builds from the handle of each
// case.
func FuzzFifoSuite[T reference.Fifo](
	f *testing.F,
	callable conform.Callable[reference.Fifo],
	newSubject func(h *FifoHandle) T,
	opts ...FifoOption,
) {
	f.Helper()
	conform.Fuzz(f, FifoSuite(), callable, fifoSubjects(newSubject), opts...)
}

// RunFifoBudgets applies the allocation ceilings of Fifo and its checks
// that count allocations, and the ceilings and the checks that opts add,
// to a fresh subject of newSubject for each case.
func RunFifoBudgets[T reference.Fifo](t *testing.T, newSubject func(h *FifoHandle) T, opts ...FifoOption) {
	t.Helper()
	conform.RunBudgets(t, FifoSuite(), fifoSubjects(newSubject), opts...)
}

// BenchFifoSuite measures callable on a subject of newSubject, under the
// ceilings of its budget.
func BenchFifoSuite[T reference.Fifo](
	b conform.B,
	callable conform.Callable[reference.Fifo],
	newSubject func(h *FifoHandle) T,
	opts ...FifoOption,
) {
	b.Helper()
	conform.Bench(b, FifoSuite(), callable, fifoSubjects(newSubject), opts...)
}

// fifoSubjects returns the factory of the subjects of Fifo that calls
// newSubject with the handle of each check.
func fifoSubjects[T reference.Fifo](newSubject func(h *FifoHandle) T) func(h *FifoHandle) reference.Fifo {
	return func(h *FifoHandle) reference.Fifo { return newSubject(h) }
}

