// fifoActions returns the actions of the generated sequences of Fifo over
// the subject that subject returns. The actions of a case take their keys
// from the pools that it draws.
func fifoActions(c *prop.Case, subject func() reference.Fifo) []stateful.Action[struct{}] {
	return []stateful.Action[struct{}]{
		{
			Name: "Push",
			Input: func(c *prop.Case, _ struct{}) any {
				item := c.Draw(prop.Of[string](), "push.item")
				return []any{item}
			},
			Run: func(c *prop.Case, client int, input any) {
				args, _ := input.([]any)
				call := c.History().Invoke(client, "Push", args)
				values, err := fifoPushCall(c.Context(), subject(), args)
				conform.Complete(c.Context(), call, err, values...)
			},
		},
		{
			Name: "Pop",
			Run: func(c *prop.Case, client int, input any) {
				args, _ := input.([]any)
				call := c.History().Invoke(client, "Pop", args)
				values, err := fifoPopCall(c.Context(), subject(), args)
				conform.Complete(c.Context(), call, err, values...)
			},
		},
		{
			Name: "Len",
			Run: func(c *prop.Case, client int, input any) {
				args, _ := input.([]any)
				call := c.History().Invoke(client, "Len", args)
				values, err := fifoLenCall(c.Context(), subject(), args)
				conform.Complete(c.Context(), call, err, values...)
			},
		},
	}
}

// fifoPushCall calls Push on subject with the arguments args, and returns
// the values of the call beside its error.
func fifoPushCall(ctx context.Context, subject reference.Fifo, args []any) ([]any, error) {
	a0, _ := args[0].(string)
	return nil, subject.Push(ctx, a0)
}

// fifoPopCall calls Pop on subject with the arguments args, and returns
// the values of the call beside its error.
func fifoPopCall(ctx context.Context, subject reference.Fifo, args []any) ([]any, error) {
	r0, err := subject.Pop(ctx)
	return []any{r0}, err
}

// fifoLenCall calls Len on subject with the arguments args, and returns
// the values of the call beside its error.
func fifoLenCall(ctx context.Context, subject reference.Fifo, args []any) ([]any, error) {
	r0, err := subject.Len(ctx)
	return []any{r0}, err
}

// fifoReference returns the function that applies an operation of a
// history to the reference r by the name of its callable.
func fifoReference(r reference.Fifo) func(context.Context, string, []any) conform.Output {
	return func(ctx context.Context, operation string, args []any) conform.Output {
		var values []any
		var err error
		switch operation {
		case "Push":
			values, err = fifoPushCall(ctx, r, args)
		case "Pop":
			values, err = fifoPopCall(ctx, r, args)
		case "Len":
			values, err = fifoLenCall(ctx, r, args)
		}
		return conform.OutputOf(err, values...)
	}
}

